int main(){try{auto g=loadGraph("work/roundtrip-11.dmx");if(sessionModelSkinCandidate(g,2552)!=0)throw std::runtime_error("fixture skin expected zero");for(auto&a:g.elements[2552].attributes)if(g.strings[a.name]=="skin"){int32_t value=1;std::memcpy(a.values[0].wire.data(),&value,4);}saveGraph(g,"work/invalid-skin-session-v2.dmx");for(auto&a:g.elements[2552].attributes)if(g.strings[a.name]=="skin"){int32_t value=0;std::memcpy(a.values[0].wire.data(),&value,4);}if(!sessionModelVisibilityCandidate(g,2552))throw std::runtime_error("visible fixture expected");Attribute*flag=nullptr;for(auto&a:g.elements[2552].attributes)if(g.strings[a.name]=="visible")flag=&a;if(!flag)throw std::runtime_error("flag missing");flag->values[0].wire[0]=0;if(sessionModelVisibilityCandidate(g,2552))throw std::runtime_error("hidden model expected");saveGraph(g,"work/hidden-model-session-v2.dmx");flag->values[0].wire[0]=2;bool rejected=false;try{sessionModelVisibilityCandidate(g,2552);}catch(...){rejected=true;}if(!rejected)throw std::runtime_error("bad bool accepted");std::cout<<"model visibility fixture passed hidden session exported malformed bool rejected\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
